1	"use server";
2	
3	// Proprietary in-portal DB manager — server actions.
4	//
5	// A Nxeon-built replacement for the Adminer file we used to drop into the
6	// customer's webroot. Everything here runs SERVER-SIDE: the customer never
7	// receives a DB credential, and every query is executed as the account's SCOPED
8	// MySQL manager user (see lib/hosting-db.ts + buildDbMgrGrantSql), which MySQL
9	// confines to this account's own `<username>_*` databases and nothing else.
10	//
11	// AUTH: every action requires the authenticated OWNER of the account (or an
12	// ADMIN). Actions that RUN SQL or reveal row data additionally call
13	// assertNotImpersonating — an admin impersonating a customer must not read or
14	// mutate that customer's live data (same discipline as revealHostingSftpPassword
15	// / createHostingDatabase). Read-only "which databases exist" listing (from OUR
16	// portal tables, not the node) is owner-or-admin without that extra bar.
17	
18	import { randomBytes } from "node:crypto";
19	import { revalidatePath } from "next/cache";
20	import { db } from "./db";
21	import { requireUser, assertNotImpersonating } from "./auth";
22	import { SANDBOX } from "./sandbox";
23	import { encryptSecret } from "./crypto-box";
24	import { checkRateLimit } from "./rate-limit";
25	import { isValidUnixUsername, isValidDbIdentifier, dbMgrUserFor } from "./hosting";
26	import {
27	  dbTargetFor,
28	  runScopedSql,
29	  showTablesSql,
30	  browseTableSql,
31	  countTableSql,
32	  isPlausibleTableName,
33	  MAX_SQL_BYTES,
34	  BROWSE_PAGE_SIZE,
35	  type QueryResult,
36	} from "./hosting-db";
37	
38	export type DbMgrStatus = { ready: boolean; provisioning: boolean; enabled: boolean };
39	export type DbMgrDatabase = { name: string; status: string };
40	export type DbMgrResult = {
41	  columns: string[];
42	  rows: string[][];
43	  truncated: boolean;
44	  error: string | null;
45	  elapsedMs: number;
46	  /** For non-SELECT statements (empty result set) — a friendly "OK" note. */
47	  ok?: boolean;
48	};
49	
50	/** Owner-or-admin account load with the node relation + manager fields. */
51	async function loadOwned(accountId: string) {
52	  const user = await requireUser();
53	  const a = await db.hostingAccount.findUnique({
54	    where: { id: accountId },
55	    include: { node: { select: { sshHost: true, sshPort: true, rootPasswordEnc: true } } },
56	  });
57	  if (!a) return { error: "Account not found." as const };
58	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." as const };
59	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." as const };
60	  return { user, a };
61	}
62	
63	/** Confirm a target db name actually belongs to THIS account (defence in depth
64	 *  on top of the MySQL grant). Returns the matched row or null. */
65	async function assertOwnedDatabase(accountId: string, dbName: string) {
66	  if (!isValidDbIdentifier(dbName)) return null;
67	  return db.hostingDatabase.findFirst({ where: { accountId, name: dbName } });
68	}
69	
70	/** A short, alphanumeric (shell/SQL-safe) secret. */
71	function newSecret(len = 24): string {
72	  return randomBytes(48).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, len);
73	}
74	
75	/**
76	 * Make sure the account has a provisioned DB-manager user. Idempotent:
77	 *   - already ready → { ready:true }
78	 *   - has creds but no ACTIVE user yet (or first call) → generate creds if
79	 *     missing, queue ENSURE_DBMGR, report { provisioning:true }
80	 * Owner-or-admin + not-impersonating (this mints a live DB credential on the box).
81	 * SANDBOX: mark ready immediately (no real node).
82	 */
83	export async function ensureDbManager(accountId: string): Promise<DbMgrStatus & { error?: string }> {
84	  const ctx = await loadOwned(accountId);
85	  if ("error" in ctx) return { ready: false, provisioning: false, enabled: false, error: ctx.error };
86	  await assertNotImpersonating();
87	  const { a } = ctx;
88	  if (!isValidUnixUsername(a.username)) return { ready: false, provisioning: false, enabled: false, error: "Account not ready." };
89	
90	  if (SANDBOX) {
91	    if (!a.dbMgrReady) {
92	      await db.hostingAccount.update({
93	        where: { id: a.id },
94	        data: { dbMgrUser: dbMgrUserFor(a.username), dbMgrPassEnc: encryptSecret(newSecret()), dbMgrReady: true },
95	      });
96	    }
97	    return { ready: true, provisioning: false, enabled: true };
98	  }
99	
100	  if (a.dbMgrReady && a.dbMgrUser && a.dbMgrPassEnc) return { ready: true, provisioning: false, enabled: true };
101	
102	  // Generate + persist the manager credential once (encrypted at rest); the
103	  // worker applies it on the node. Keep the same password across re-queues so the
104	  // stored cred always matches what the node was told.
105	  if (!a.dbMgrUser || !a.dbMgrPassEnc) {
106	    await db.hostingAccount.update({
107	      where: { id: a.id },
108	      data: { dbMgrUser: dbMgrUserFor(a.username), dbMgrPassEnc: encryptSecret(newSecret()), dbMgrReady: false },
109	    });
110	  }
111	  const inFlight = await db.hostingTask.findFirst({ where: { accountId, kind: "ENSURE_DBMGR", status: { in: ["PENDING", "RUNNING"] } } });
112	  if (!inFlight) await db.hostingTask.create({ data: { accountId, kind: "ENSURE_DBMGR" } });
113	  revalidatePath(`/dashboard/hosting/${accountId}`);
114	  return { ready: false, provisioning: true, enabled: true };
115	}
116	
117	export async function dbmgrStatus(accountId: string): Promise<DbMgrStatus & { error?: string }> {
118	  const ctx = await loadOwned(accountId);
119	  if ("error" in ctx) return { ready: false, provisioning: false, enabled: false, error: ctx.error };
120	  const { a } = ctx;
121	  if (SANDBOX) return { ready: !!a.dbMgrReady, provisioning: false, enabled: true };
122	  const provisioning = !a.dbMgrReady && !!(await db.hostingTask.findFirst({ where: { accountId, kind: "ENSURE_DBMGR", status: { in: ["PENDING", "RUNNING"] } } }));
123	  return { ready: !!a.dbMgrReady, provisioning, enabled: true };
124	}
125	
126	/** The account's databases — read straight from OUR portal tables (never the
127	 *  node), so this leaks nothing and needs no MySQL round-trip. Owner-or-admin. */
128	export async function dbmgrListDatabases(accountId: string): Promise<{ error?: string; databases?: DbMgrDatabase[] }> {
129	  const ctx = await loadOwned(accountId);
130	  if ("error" in ctx) return { error: ctx.error };
131	  const rows = await db.hostingDatabase.findMany({ where: { accountId, status: { in: ["ACTIVE", "PENDING"] } }, orderBy: { createdAt: "asc" } });
132	  return { databases: rows.map((r) => ({ name: r.name, status: r.status })) };
133	}
134	
135	/** Rate-limit the SQL surface per user (a customer-exposed exec path). */
136	function rlOk(userId: string, accountId: string): boolean {
137	  return checkRateLimit(`dbmgr:${userId}:${accountId}`, { max: 60, windowMs: 60_000 }).ok;
138	}
139	
140	const SANDBOX_TABLES = ["customers", "orders", "products"];
141	function sandboxResult(sql: string): DbMgrResult {
142	  const s = sql.trim().toLowerCase();
143	  if (s.startsWith("show tables")) {
144	    return { columns: ["Tables_in_demo"], rows: SANDBOX_TABLES.map((t) => [t]), truncated: false, error: null, elapsedMs: 3 };
145	  }
146	  if (s.startsWith("select count(")) {
147	    return { columns: ["n"], rows: [["3"]], truncated: false, error: null, elapsedMs: 2 };
148	  }
149	  if (s.startsWith("select")) {
150	    return {
151	      columns: ["id", "name", "created_at"],
152	      rows: [["1", "Ada Lovelace", "2026-01-02 10:00:00"], ["2", "Grace Hopper", "2026-01-03 11:30:00"], ["3", "Katherine Johnson", "2026-01-04 09:15:00"]],
153	      truncated: false, error: null, elapsedMs: 4,
154	    };
155	  }
156	  return { columns: [], rows: [], truncated: false, error: null, elapsedMs: 2, ok: true };
157	}
158	
159	/** List a database's tables (SHOW TABLES as the scoped user). Owner-or-admin +
160	 *  not-impersonating (it reaches the customer's live data). */
161	export async function dbmgrListTables(accountId: string, dbName: string): Promise<{ error?: string; tables?: string[] }> {
162	  const ctx = await loadOwned(accountId);
163	  if ("error" in ctx) return { error: ctx.error };
164	  await assertNotImpersonating();
165	  const { user } = ctx;
166	  if (!(await assertOwnedDatabase(accountId, dbName))) return { error: "Unknown database." };
167	  if (!rlOk(user.id, accountId)) return { error: "Too many requests — slow down a moment." };
168	  if (SANDBOX) return { tables: SANDBOX_TABLES };
169	  const target = dbTargetFor(ctx.a);
170	  if (!target) return { error: "The database manager is still being prepared." };
171	  const res = await runScopedSql(target, dbName, showTablesSql());
172	  if (res.error) return { error: res.error };
173	  return { tables: res.rows.map((r) => r[0]).filter(Boolean) };
174	}
175	
176	/** Browse a page of a table's rows. Validates the table by MEMBERSHIP against the
177	 *  db's real table list (so a user can't name a table they can't see), then runs
178	 *  a bounded SELECT + a COUNT. Owner-or-admin + not-impersonating. */
179	export async function dbmgrBrowseTable(
180	  accountId: string,
181	  dbName: string,
182	  table: string,
183	  page: number,
184	): Promise<{ error?: string; columns?: string[]; rows?: string[][]; total?: number | null; page?: number; pageSize?: number; truncated?: boolean }> {
185	  const ctx = await loadOwned(accountId);
186	  if ("error" in ctx) return { error: ctx.error };
187	  await assertNotImpersonating();
188	  const { user } = ctx;
189	  if (!(await assertOwnedDatabase(accountId, dbName))) return { error: "Unknown database." };
190	  if (!isPlausibleTableName(table)) return { error: "Invalid table name." };
191	  if (!rlOk(user.id, accountId)) return { error: "Too many requests — slow down a moment." };
192	  const p = Math.max(0, Math.floor(Number(page) || 0));
193	
194	  if (SANDBOX) {
195	    const demo = sandboxResult("select");
196	    return { columns: demo.columns, rows: demo.rows, total: demo.rows.length, page: p, pageSize: BROWSE_PAGE_SIZE, truncated: false };
197	  }
198	  const target = dbTargetFor(ctx.a);
199	  if (!target) return { error: "The database manager is still being prepared." };
200	
201	  // Membership check: the table MUST be one the scoped user can actually see.
202	  const listed = await runScopedSql(target, dbName, showTablesSql());
203	  if (listed.error) return { error: listed.error };
204	  const tables = listed.rows.map((r) => r[0]);
205	  if (!tables.includes(table)) return { error: "Unknown table." };
206	
207	  const res = await runScopedSql(target, dbName, browseTableSql(table, BROWSE_PAGE_SIZE, p * BROWSE_PAGE_SIZE));
208	  if (res.error) return { error: res.error };
209	  const countRes = await runScopedSql(target, dbName, countTableSql(table));
210	  const total = countRes.error ? null : Number(countRes.rows[0]?.[0] ?? "0");
211	  return { columns: res.columns, rows: res.rows, total: Number.isFinite(total as number) ? (total as number) : null, page: p, pageSize: BROWSE_PAGE_SIZE, truncated: res.truncated };
212	}
213	
214	/**
215	 * Run arbitrary SQL scoped to one of the account's databases. The SQL travels to
216	 * the node's `mysql` client over STDIN (never a shell), executed as the scoped
217	 * manager user — MySQL's grant is the hard isolation boundary. Owner-or-admin +
218	 * not-impersonating + rate-limited.
219	 */
220	export async function dbmgrRunSql(accountId: string, dbName: string, sql: string): Promise<DbMgrResult> {
221	  const empty: DbMgrResult = { columns: [], rows: [], truncated: false, error: null, elapsedMs: 0 };
222	  const ctx = await loadOwned(accountId);
223	  if ("error" in ctx) return { ...empty, error: ctx.error ?? null };
224	  await assertNotImpersonating();
225	  const { user } = ctx;
226	  if (!(await assertOwnedDatabase(accountId, dbName))) return { ...empty, error: "Unknown database." };
227	  const text = String(sql ?? "").trim();
228	  if (!text) return { ...empty, error: "Enter a SQL statement." };
229	  if (Buffer.byteLength(text, "utf8") > MAX_SQL_BYTES) return { ...empty, error: "That query is too large." };
230	  if (!rlOk(user.id, accountId)) return { ...empty, error: "Too many requests — slow down a moment." };
231	
232	  if (SANDBOX) return sandboxResult(text);
233	  const target = dbTargetFor(ctx.a);
234	  if (!target) return { ...empty, error: "The database manager is still being prepared." };
235	  const res: QueryResult = await runScopedSql(target, dbName, text);
236	  if (res.error) return { ...res, error: res.error };
237	  return { ...res, ok: res.columns.length === 0 };
238	}
