111	 * the node has one, for sub-domains / apex-ALIAS providers.)
112	 */
113	export function pointToRecords(node: { publicIp: string; hostnameFqdn?: string | null }): {
114	  aRecord: string;
115	  cnameTarget: string | null;
116	} {
