151	/**
152	 * A hard-to-guess token for the Adminer DB-manager directory dropped inside an
153	 * account's webroot (`/nxtools-<token>/adminer.php`). Lowercase alnum only, so it
154	 * is shell-inert AND a valid nginx-served directory name; length-bounded to keep
155	 * it unguessable without being unwieldy. The real access control is the tenant's
156	 * scoped DB login, not the token — this just keeps the path off casual discovery.
157	 */
158	const DBTOOL_TOKEN_RE = /^[a-z0-9]{16,40}$/;
159	export function isValidDbToolToken(token: string): boolean {
160	  return DBTOOL_TOKEN_RE.test(String(token ?? ""));
