163	/** Docroot + parent dir for a subdomain, jailed under the account home. */
164	export function subdomainPaths(username: string, label: string): { dir: string; docroot: string } {
165	  const dir = `/home/${username}/subdomains/${label}`;
166	  return { dir, docroot: `${dir}/public_html` };
