169	/** Docroot + parent dir for an addon domain, jailed under the account home. */
170	export function addonDomainPaths(username: string, domain: string): { dir: string; docroot: string } {
171	  const dir = `/home/${username}/domains/${domain}`;
172	  return { dir, docroot: `${dir}/public_html` };
