175	/**
176	 * True for a well-formed 5-field cron schedule ("m h dom mon dow"). Each field is
177	 * restricted to the digits/ranges/steps/lists/`*` cron uses — nothing that could
178	 * be a shell metacharacter — so the schedule is safe to write into a crontab.
179	 * (Named shortcuts like @daily are intentionally NOT accepted here.)
180	 */
181	const CRON_FIELD_RE = /^[0-9*/,\-]+$/;
182	export function isValidCronSchedule(schedule: string): boolean {
183	  const parts = String(schedule ?? "").trim().split(/\s+/);
184	  if (parts.length !== 5) return false;
185	  return parts.every((p) => p.length > 0 && p.length <= 40 && CRON_FIELD_RE.test(p));
186	}
187	
188	/**
189	 * True for a cron command safe to place in a crontab line. It runs AS the jailed
190	 * user (crontab -u <user>), so it is already confined; the only invariants we
191	 * enforce here protect our own crontab writer: no newlines (one line per job) and
192	 * no `%` (cron's literal-newline metacharacter), and a sane length.
193	 */
194	export function isValidCronCommand(command: string): boolean {
195	  const c = String(command ?? "");
196	  if (c.length < 1 || c.length > 500) return false;
197	  return !/[\n\r%]/.test(c);
198	}
