200	/* ------------------------------------------------------------------------- *
201	 * Provisioner hardening (config generators for NEW accounts)
202	 *
203	 * These are the security-critical config the provisioner writes onto a
204	 * MULTI-TENANT box. They are pure + unit-tested here because a subtle gap in
205	 * any of them (a missing dangerous PHP function, a world-readable webroot, an
206	 * un-escaped GRANT wildcard) is not one customer's bug — it is a cross-tenant
207	 * breach. worker/hosting.ts imports these; it never re-derives them inline.
208	 * ------------------------------------------------------------------------- */
209	
210	/**
211	 * PHP functions blocked in every account's FPM pool (`disable_functions`).
212	 *
213	 * On a shared box `disable_functions` is a real isolation control, not defence
214	 * in depth: without it a tenant's PHP can shell out (`exec`/`system`), fork out
215	 * of `open_basedir` (`pcntl_exec` — compiled into PHP, so it bypasses a naive
216	 * blocklist), rewrite its own env (`putenv` → `LD_PRELOAD`/`GCONV_PATH`
217	 * tricks), plant symlinks that escape the jail (`symlink`/`link`), or reach the
218	 * host via `ffi`/`dl`. Everything a tenant could use to break out of its pool
219	 * belongs here. Kept sorted-by-purpose + deduped.
220	 */
221	export const PHP_DISABLED_FUNCTIONS: readonly string[] = [
222	  // Command execution — the classic RCE surface.
223	  "exec", "passthru", "shell_exec", "system", "proc_open", "popen",
224	  // Process control — pcntl_exec is compiled in and bypasses the above blocklist;
225	  // fork/signal/proc_nice let a tenant escape open_basedir or starve neighbours.
226	  "pcntl_exec", "pcntl_fork", "pcntl_signal", "proc_nice",
227	  // Environment + dynamic loading — putenv enables LD_PRELOAD-style escapes,
228	  // dl/ffi load native code straight past the PHP sandbox.
229	  "putenv", "dl", "ffi",
230	  // Filesystem jail-breaks — symlink/link can point out of open_basedir.
231	  "symlink", "link",
232	  // Mail — a shared box is a prized spam relay. mail() is blocked; mb_send_mail
233	  // is an equivalent wrapper, and imap_open/imap_mail can send too — block all.
234	  "mail", "mb_send_mail", "imap_open", "imap_mail",
235	  // Misc host-reach / info-leak vectors.
236	  "error_log", "curl_multi_exec", "parse_ini_file", "show_source",
237	] as const;
238	
239	/** The comma-separated `disable_functions` value for a pool config. */
240	export function phpDisableFunctions(): string {
241	  return [...PHP_DISABLED_FUNCTIONS].join(",");
242	}
243	
244	/**
245	 * Filesystem ownership + permission plan for a new account.
246	 *
247	 * The isolation goal: nginx (www-data) must serve a tenant's files, but a
248	 * NEIGHBOURING tenant (its own jailed unix user) must not be able to read them
249	 * — so nothing here is world-readable (the old `755` webroot let any tenant
250	 * read a peer's wp-config.php if open_basedir was ever escaped).
251	 *
252	 *  - home    `711 root:root` — chroot-safe (root-owned, no group/other write)
253	 *            and world-traversable so nginx can *reach* the webroot, but NOT
254	 *            world-listable, so a peer can't enumerate the home.
255	 *  - webroot `2750 <user>:www-data` — owner (the tenant's FPM pool) read/write,
256	 *            group www-data (nginx) read, world nothing. The setgid bit makes
257	 *            files the tenant creates inherit the www-data group so nginx keeps
258	 *            serving them; peers (neither owner nor in www-data) are shut out.
259	 *  - tmp     `700 <user>:<user>` — private PHP scratch (upload/session dir).
260	 *
261	 * nginx reaches tenant files via GROUP membership (www-data owns the webroot
262	 * group), never via world bits — that is the whole point of dropping 755.
263	 */
264	export function accountFsPlan(username: string): {
265	  home: { owner: string; mode: string };
266	  webroot: { owner: string; mode: string };
267	  tmp: { owner: string; mode: string };
268	  nginxGroup: string;
269	} {
270	  return {
271	    home: { owner: "root:root", mode: "711" },
272	    webroot: { owner: `${username}:www-data`, mode: "2750" },
273	    tmp: { owner: `${username}:${username}`, mode: "700" },
274	    nginxGroup: "www-data",
275	  };
276	}
277	
278	/** PHP-FPM pool hardening limits applied to every account pool. */
279	export const FPM_MEMORY_LIMIT = "256M";
280	export const FPM_REQUEST_TERMINATE_TIMEOUT = "120s";
281	
282	/**
283	 * The per-account PHP-FPM pool config (the PHP isolation boundary). Pure: given
284	 * the validated username + jailed paths, returns the exact pool file contents.
285	 *
286	 * open_basedir is scoped to the account home (+ the shared PHP lib) and NO
287	 * LONGER includes `/tmp`: PHP's tmp/session dirs are redirected into the home,
288	 * so a world-writable `/tmp` on open_basedir was just an unnecessary shared
289	 * surface between tenants. memory_limit + request_terminate_timeout cap a
290	 * single tenant from exhausting the shared box.
291	 */
292	export function fpmPoolConfig(username: string, home: string, webroot: string): string {
293	  const sock = `/run/php/${username}.sock`;
294	  return [
295	    `[${username}]`,
296	    `user = ${username}`,
297	    `group = ${username}`,
298	    `listen = ${sock}`,
299	    `listen.owner = ${username}`,
300	    `listen.group = www-data`,
301	    `pm = ondemand`,
302	    `pm.max_children = 6`,
303	    `pm.process_idle_timeout = 30s`,
304	    `chdir = ${webroot}`,
305	    // TRAILING SLASHES are load-bearing: `${home}` (no slash) would also authorise
306	    // `${home}2/…` — a sibling tenant's home — so open_basedir must pin the prefix
307	    // to the directory itself via the trailing `/` (same for the shared PHP lib).
308	    `php_admin_value[open_basedir] = ${home}/:/usr/share/php/`,
309	    `php_admin_value[disable_functions] = ${phpDisableFunctions()}`,
310	    `php_admin_value[memory_limit] = ${FPM_MEMORY_LIMIT}`,
311	    `php_admin_value[request_terminate_timeout] = ${FPM_REQUEST_TERMINATE_TIMEOUT}`,
312	    `php_admin_value[upload_tmp_dir] = ${home}/tmp`,
313	    `php_admin_value[session.save_path] = ${home}/tmp`,
314	  ].join("\n");
315	}
