317	/**
318	 * Escape a MySQL identifier for the `ON <db>.*` clause of a GRANT.
319	 *
320	 * In GRANT, `_` and `%` are LIKE-wildcards: an un-escaped grant on `nxuser_wp`
321	 * silently also grants on `nxuserXwp`, `nxuser_wpZ`, … i.e. a neighbouring
322	 * tenant's database. Escaping them (and the escape char itself) with a
323	 * backslash pins the grant to exactly one database.
324	 */
325	export function escapeGrantDbName(name: string): string {
326	  return name.replace(/([\\_%])/g, "\\$1");
327	}
328	
329	/**
330	 * The scoped SQL that creates one account database + user and grants that user
331	 * privileges on THAT DATABASE ONLY.
332	 *
333	 * Security invariants (audited): the GRANT is pinned to the exact db via
334	 * escapeGrantDbName (no wildcard bleed into a peer's db), it is NEVER `*.*`,
335	 * and `ALL PRIVILEGES` at database scope confers no global FILE/SUPER (those
336	 * are server-level and cannot be granted by a db-scoped GRANT). Returns plain
337	 * SQL with real backticks; the caller shell-escapes for `mysql -e`.
338	 */
339	export function buildScopedGrantSql(dbName: string, dbUser: string, dbPass: string): string {
340	  const grantName = escapeGrantDbName(dbName);
341	  return (
342	    `CREATE DATABASE IF NOT EXISTS \`${dbName}\`; ` +
343	    `CREATE USER IF NOT EXISTS '${dbUser}'@'localhost' IDENTIFIED BY '${dbPass}'; ` +
344	    `GRANT ALL PRIVILEGES ON \`${grantName}\`.* TO '${dbUser}'@'localhost'; ` +
345	    `FLUSH PRIVILEGES;`
346	  );
347	}
348	
349	// ---- Proprietary in-portal DB manager (Nxeon-built, replaces Adminer) -------
350	
351	/** The account-level MySQL user the in-portal DB manager authenticates as. One
352	 *  per account, derived from the (already shell/SQL-safe) username. Kept <=32
353	 *  chars — MySQL's user-name limit. Usernames are `[a-z][a-z0-9]{2,31}` (no
354	 *  underscore), so `<username>_mgr` is unambiguous and never collides with a
355	 *  per-database user (`<username>_<slug>`) whose slug can't be the reserved
356	 *  literal `mgr` used here… — we simply reserve this name for the manager. */
357	export function dbMgrUserFor(username: string): string {
358	  return `${username}_mgr`.slice(0, 32);
359	}
360	
361	/** Is this a syntactically valid MySQL account/database identifier for OUR
362	 *  generated names? Deliberately strict — only the charset our provisioner ever
363	 *  produces (`<username>_<slug>` / `<username>_mgr`), so a value that reaches the
364	 *  `mysql` command line as a flag can carry no shell metacharacters. NOT for
365	 *  arbitrary user-supplied table names (those are validated by membership against
366	 *  SHOW TABLES + backtick-quoting, never interpolated into a shell). */
367	const DB_IDENT_RE = /^[a-z0-9_]{1,64}$/;
368	export function isValidDbIdentifier(name: string): boolean {
369	  return DB_IDENT_RE.test(String(name ?? ""));
370	}
371	
372	/**
373	 * The grant that scopes the DB-manager user to EXACTLY this account's own
374	 * databases and nothing else. The privilege target is `<username>\_%`.* — the
375	 * account username, a LITERAL underscore (escaped so it is not a LIKE wildcard),
376	 * then `%`. That matches every `<username>_<...>` database the account can create
377	 * and, because usernames are `[a-z][a-z0-9]{2,31}` (never contain `_`), can never
378	 * match another tenant's `<otheruser>_<...>` databases — the same escaped-glob
379	 * boundary the backup/terminate paths already rely on.
380	 *
381	 * Security invariants (mirror buildScopedGrantSql): the grant is db-scoped, never
382	 * `*.*`, so `ALL PRIVILEGES` here confers NO server-level FILE/PROCESS/SUPER — the
383	 * manager user therefore cannot read files (LOAD_FILE/INTO OUTFILE), see other
384	 * connections, or touch the `mysql`/system schemas. Returns plain SQL with real
385	 * backticks; the caller shell-escapes for `mysql -e`.
386	 */
387	export function buildDbMgrGrantSql(username: string, mgrUser: string, mgrPass: string): string {
388	  // `${username}\_%` — escape only the underscore (username itself is [a-z0-9]).
389	  const scope = `${username}\\_%`;
390	  return (
391	    `CREATE USER IF NOT EXISTS '${mgrUser}'@'localhost' IDENTIFIED BY '${mgrPass}'; ` +
392	    `ALTER USER '${mgrUser}'@'localhost' IDENTIFIED BY '${mgrPass}'; ` +
393	    `GRANT ALL PRIVILEGES ON \`${scope}\`.* TO '${mgrUser}'@'localhost'; ` +
394	    `FLUSH PRIVILEGES;`
395	  );
396	}
