1	import { NextRequest, NextResponse } from "next/server";
2	import { requireUser } from "@/lib/auth";
3	import { db } from "@/lib/db";
4	import { fsReadBuffer, fsWriteBuffer, fsStatSize, fsTargetFor } from "@/lib/hosting-fs";
5	import { SANDBOX } from "@/lib/sandbox";
6	
7	const MAX_UPLOAD = 100 * 1024 * 1024;
8	// Downloads buffer the whole file in memory (Buffer.concat), so cap the size we're
9	// willing to read to keep one tenant's giant file from OOMing the panel (MEDIUM-3).
10	const MAX_DOWNLOAD = 100 * 1024 * 1024;
11	
12	async function ownedNode(accountId: string) {
13	  const user = await requireUser();
14	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, include: { node: true } });
15	  if (!a) return null;
16	  if (a.userId !== user.id && user.role !== "ADMIN") return null;
17	  if (a.status !== "ACTIVE") return null;
18	  return a;
19	}
20	
21	/** Upload a file into the account webroot (jailed). ?accountId=&path= */
22	export async function POST(req: NextRequest) {
23	  const a = await ownedNode(req.nextUrl.searchParams.get("accountId") ?? "");
24	  if (!a) return NextResponse.json({ error: "Forbidden" }, { status: 403 });
25	  const dir = req.nextUrl.searchParams.get("path") ?? "public_html";
26	  const form = await req.formData();
27	  const file = form.get("file");
28	  if (!(file instanceof File)) return NextResponse.json({ error: "No file" }, { status: 400 });
29	  if (file.size > MAX_UPLOAD) return NextResponse.json({ error: "File too large (max 100 MB)" }, { status: 413 });
30	  const safeName = file.name.replace(/[^A-Za-z0-9._-]/g, "_").slice(0, 120);
31	  if (SANDBOX) return NextResponse.json({ ok: true });
32	  const t = fsTargetFor(a);
33	  if (!t) return NextResponse.json({ error: "File manager not ready" }, { status: 409 });
34	  try {
35	    await fsWriteBuffer(t, `${dir}/${safeName}`, Buffer.from(await file.arrayBuffer()));
36	    return NextResponse.json({ ok: true, name: safeName });
37	  } catch {
38	    return NextResponse.json({ error: "Upload failed" }, { status: 500 });
39	  }
40	}
41	
42	/** Download a file from the account (jailed). ?accountId=&path= */
43	export async function GET(req: NextRequest) {
44	  const a = await ownedNode(req.nextUrl.searchParams.get("accountId") ?? "");
45	  if (!a) return new NextResponse("Forbidden", { status: 403 });
46	  const path = req.nextUrl.searchParams.get("path") ?? "";
47	  if (SANDBOX) return new NextResponse("sandbox", { status: 200 });
48	  const t = fsTargetFor(a);
49	  if (!t) return new NextResponse("Not ready", { status: 409 });
50	  try {
51	    // Stat first and refuse anything over the cap, so we never Buffer.concat a
52	    // huge file into memory (OOM DoS, MEDIUM-3).
53	    const size = await fsStatSize(t, path);
54	    if (size > MAX_DOWNLOAD) return new NextResponse("File too large to download (max 100 MB)", { status: 413 });
55	    const buf = await fsReadBuffer(t, path);
56	    const name = path.split("/").pop() ?? "download";
57	    return new NextResponse(new Uint8Array(buf), { status: 200, headers: { "Content-Type": "application/octet-stream", "Content-Disposition": `attachment; filename="${name.replace(/"/g, "")}"` } });
58	  } catch {
59	    return new NextResponse("Not found", { status: 404 });
60	  }
61	}
