60	/** Shell-escape the raw SQL from buildScopedGrantSql for embedding in a
61	 *  double-quoted `mysql -e "..."`. Identifiers/passwords are already validated
62	 *  to safe charsets; only the SQL's own backticks need escaping so the shell
63	 *  doesn't treat them as command substitution. */
64	function sqlForMysqlExec(sql: string): string {
65	  return sql.replace(/`/g, "\\`");
66	}
