69	const CONNECT_TIMEOUT_MS = 20_000;
70	const STEP_TIMEOUT_MS = 60_000;
71	/** Node hardening runs the whole onboard script (apt installs — ModSecurity,
72	 *  ClamAV — take minutes), so it gets a much longer ceiling than a single step. */
73	const HARDEN_TIMEOUT_MS = 15 * 60_000;
