78	/** Alphanumeric password (shell/SQL-safe: no quoting hazards). */
79	function strongPassword(len = 22): string {
80	  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
81	  const bytes = randomBytes(len);
82	  let out = "";
83	  for (let i = 0; i < len; i++) out += alphabet[bytes[i] % alphabet.length];
84	  return out;
85	}
