87	async function connectNode(node: { sshHost: string; sshPort: number; rootPasswordEnc: string | null }): Promise<Client> {
88	  const password = node.rootPasswordEnc ? decryptSecret(node.rootPasswordEnc) : "";
89	  if (!password) throw new Error("Hosting node has no root credential on record.");
90	  const conn = new Client();
91	  await new Promise<void>((resolve, reject) => {
92	    const timer = setTimeout(() => { try { conn.end(); } catch { /* */ } reject(new Error("SSH connect timed out")); }, CONNECT_TIMEOUT_MS);
93	    conn
94	      .on("ready", () => { clearTimeout(timer); resolve(); })
95	      .on("error", (e) => { clearTimeout(timer); reject(e); })
96	      .connect({ host: node.sshHost, port: node.sshPort, username: "root", password, readyTimeout: CONNECT_TIMEOUT_MS });
97	  });
98	  return conn;
99	}
100	
101	function exec(conn: Client, command: string, timeoutMs = STEP_TIMEOUT_MS): Promise<{ code: number; out: string }> {
102	  return new Promise((resolve, reject) => {
103	    const timer = setTimeout(() => reject(new Error("command timed out")), timeoutMs);
104	    conn.exec(command, (err, stream) => {
105	      if (err) { clearTimeout(timer); return reject(err); }
106	      let out = "";
107	      stream
108	        .on("close", (code: number) => { clearTimeout(timer); resolve({ code: code ?? 0, out }); })
109	        .on("data", (d: Buffer) => { out += d.toString(); })
110	        .stderr.on("data", (d: Buffer) => { out += d.toString(); });
111	    });
112	  });
113	}
114	
115	async function run(conn: Client, label: string, cmd: string): Promise<void> {
116	  const r = await exec(conn, cmd, STEP_TIMEOUT_MS);
117	  if (r.code !== 0) throw new Error(`${label} failed: ${r.out.slice(0, 300)}`);
118	}
