120	/**
121	 * The name-based nginx vhost for one account. It ALWAYS emits a `listen 443 ssl`
122	 * server block so nginx answers HTTPS from the moment the account exists —
123	 * `ssl.certDir` is the real Let's Encrypt live dir when `ssl.real` is true, else
124	 * the per-account SELF-SIGNED fallback generated at provision time. That is the
125	 * whole "clean setup always" guarantee: HTTPS shows a cert WARNING, never
126	 * ERR_CONNECTION_REFUSED. The HTTP→HTTPS redirect fires ONLY once a real cert
127	 * exists; a self-signed site still serves its body over both 80 and 443 (so it
128	 * can't 301-loop a visitor into an untrusted-cert dead end). Shared IP; routed
129	 * purely by server_name; PHP proxied to THIS account's socket only, root jailed to
130	 * its webroot. Pure string — no interpolation reaches a shell here.
131	 */
132	function renderHostingVhost(username: string, domain: string, webroot: string, sock: string, ssl: { certDir: string; real: boolean }): string {
133	  const phpLoc = [
134	    `    location ~ \\.php$ {`,
135	    `        include fastcgi_params;`,
136	    `        fastcgi_pass unix:${sock};`,
137	    `        fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;`,
138	    `    }`,
139	  ].join("\n");
140	  const body = [
141	    `    root ${webroot};`,
142	    // Refuse to follow a symlink whose target isn't owned by the same user as the
143	    // link — blocks a tenant symlinking to a victim's wp-config.php that nginx
144	    // (www-data) would otherwise happily serve (cross-tenant read, audit CRITICAL-1).
145	    `    disable_symlinks if_not_owner;`,
146	    `    index index.php index.html;`,
147	    `    location / { try_files $uri $uri/ /index.php?$query_string; }`,
148	    phpLoc,
149	    `    location ~ /\\. { deny all; }`,
150	  ].join("\n");
151	  const http = [
152	    `server {`,
153	    `    listen 80;`,
154	    `    listen [::]:80;`,
155	    `    server_name ${domain} www.${domain};`,
156	    `    location ^~ /.well-known/acme-challenge/ { root /var/www/html; }`,
157	    // Redirect to HTTPS only with a REAL cert; a self-signed site serves over 80 too.
158	    ssl.real ? `    location / { return 301 https://$host$request_uri; }` : body,
159	    `}`,
160	  ].join("\n");
161	  const https = [
162	    `server {`,
163	    `    listen 443 ssl;`,
164	    `    listen [::]:443 ssl;`,
165	    `    server_name ${domain} www.${domain};`,
166	    `    ssl_certificate ${ssl.certDir}/fullchain.pem;`,
167	    `    ssl_certificate_key ${ssl.certDir}/privkey.pem;`,
168	    `    ssl_protocols TLSv1.2 TLSv1.3;`,
169	    body,
170	    `}`,
171	  ].join("\n");
172	  return `${http}\n${https}\n`;
173	}
