175	/** Write a vhost file + enable it, tested before reload. */
176	async function installVhost(conn: Client, username: string, conf: string): Promise<void> {
177	  const path = `/etc/nginx/sites-available/hosting-${username}.conf`;
178	  await run(conn, "write vhost", `cat > ${path} <<'VH'\n${conf}VH\nln -sfn ${path} /etc/nginx/sites-enabled/hosting-${username}.conf`);
179	  await run(conn, "test + reload nginx", `nginx -t && systemctl reload nginx`);
180	}
