182	/**
183	 * A single extra site (subdomain / addon domain): its own docroot + PHP socket,
184	 * one `server_name`. Same shape as renderHostingVhost but keyed on an explicit
185	 * server_name string so it can serve a subdomain OR an addon domain. Pure — no
186	 * interpolation reaches a shell here (the caller validated every part).
187	 */
188	function renderSiteVhost(serverName: string, docroot: string, sock: string, sslLiveDir: string | null): string {
189	  const phpLoc = [
190	    `    location ~ \\.php$ {`,
191	    `        include fastcgi_params;`,
192	    `        fastcgi_pass unix:${sock};`,
193	    `        fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;`,
194	    `    }`,
195	  ].join("\n");
196	  const body = [
197	    `    root ${docroot};`,
198	    // Refuse a symlink whose target isn't owned by the link's owner — a tenant
199	    // can't symlink a neighbour's file into a served path (audit CRITICAL-1).
200	    `    disable_symlinks if_not_owner;`,
201	    `    index index.php index.html;`,
202	    `    location / { try_files $uri $uri/ /index.php?$query_string; }`,
203	    phpLoc,
204	    `    location ~ /\\. { deny all; }`,
205	  ].join("\n");
206	  const http = [
207	    `server {`,
208	    `    listen 80;`,
209	    `    listen [::]:80;`,
210	    `    server_name ${serverName};`,
211	    `    location ^~ /.well-known/acme-challenge/ { root /var/www/html; }`,
212	    sslLiveDir ? `    location / { return 301 https://$host$request_uri; }` : body,
213	    `}`,
214	  ].join("\n");
215	  if (!sslLiveDir) return http + "\n";
216	  const https = [
217	    `server {`,
218	    `    listen 443 ssl;`,
219	    `    listen [::]:443 ssl;`,
220	    `    server_name ${serverName};`,
221	    `    ssl_certificate ${sslLiveDir}/fullchain.pem;`,
222	    `    ssl_certificate_key ${sslLiveDir}/privkey.pem;`,
223	    `    ssl_protocols TLSv1.2 TLSv1.3;`,
224	    body,
225	    `}`,
226	  ].join("\n");
227	  return `${http}\n${https}\n`;
228	}
