244	/** Write + (re)load an account's FPM pool for a given PHP version. The pool
245	 *  contents (the PHP isolation boundary) come from the tested pure generator in
246	 *  lib/hosting.ts — socket path is unchanged across versions so the vhost never
247	 *  needs editing when PHP is switched. */
248	async function writeFpmPool(conn: Client, u: string, home: string, webroot: string, php: string): Promise<void> {
249	  if (!/^\d\.\d$/.test(php)) throw new Error(`refusing unsafe php version ${php}`);
250	  await run(conn, "php-fpm pool", `cat > /etc/php/${php}/fpm/pool.d/${u}.conf <<'POOL'\n${fpmPoolConfig(u, home, webroot)}\nPOOL\nsystemctl reload php${php}-fpm 2>/dev/null || systemctl restart php${php}-fpm`);
251	}
