347	/** Create ONE scoped MySQL/MariaDB user+db on the account's node. */
348	async function provisionHostingDatabase(dbId: string): Promise<void> {
349	  const rec = await db.hostingDatabase.findUnique({ where: { id: dbId }, include: { account: { include: { node: true } } } });
350	  if (!rec || rec.status !== "PENDING") return;
351	  if (SANDBOX || !ENABLED) {
352	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: SANDBOX ? "ACTIVE" : "PENDING", passwordEnc: null, error: SANDBOX ? null : "Shared hosting not enabled." } });
353	    return;
354	  }
355	  const name = rec.name;
356	  const user = rec.dbUser;
357	  const pass = rec.passwordEnc ? decryptSecret(rec.passwordEnc) : "";
358	  // DB name + user were built from the validated username; re-assert shape.
359	  if (!/^[a-z0-9_]{1,64}$/.test(name) || !/^[a-z0-9_]{1,32}$/.test(user) || !pass) {
360	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: "FAILED", error: "invalid db identifiers" } });
361	    return;
362	  }
363	  try {
364	    const conn = await connectNode(rec.account.node);
365	    try {
366	      // Grants scoped to THIS database only — the data-isolation boundary.
367	      // buildScopedGrantSql escapes _/% so the GRANT can't bleed onto a peer's db.
368	      const sql = sqlForMysqlExec(buildScopedGrantSql(name, user, pass));
369	      await run(conn, "create database", `mysql -e "${sql}"`);
370	    } finally {
371	      try { conn.end(); } catch { /* */ }
372	    }
373	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: "ACTIVE", passwordEnc: null, error: null } });
374	  } catch (e) {
375	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: "FAILED", error: (e instanceof Error ? e.message : String(e)).slice(0, 300) } });
376	  }
377	}
