379	export async function hostingDatabaseSweep(): Promise<void> {
380	  const pending = await db.hostingDatabase.findMany({ where: { status: "PENDING" }, select: { id: true }, take: 10 });
381	  for (const p of pending) await provisionHostingDatabase(p.id).catch((e) => console.error(`[hosting] db ${p.id} failed`, e));
382	}
