386	export async function provisionHostingAccount(accountId: string): Promise<void> {
387	  const account = await db.hostingAccount.findUnique({ where: { id: accountId }, include: { node: true, plan: true } });
388	  if (!account || account.status !== "PENDING") return;
389	  await db.hostingAccount.update({ where: { id: account.id }, data: { status: "PROVISIONING", error: null } });
390	
391	  if (SANDBOX || !ENABLED) {
392	    if (SANDBOX) {
393	      const pw = strongPassword();
394	      await db.hostingAccount.update({ where: { id: account.id }, data: { status: "ACTIVE", provisionedAt: new Date(), sftpPasswordEnc: encryptSecret(pw), error: null } });
395	    } else {
396	      await db.hostingAccount.update({ where: { id: account.id }, data: { status: "PENDING", error: "Shared hosting is not enabled on this deployment yet." } });
397	    }
398	    return;
399	  }
400	
401	  try {
402	    const allowed = planLimits(account.plan).phpVersions;
403	    const php = allowed.includes(account.phpVersion) ? account.phpVersion : allowed[0];
404	    const sftpPassword = strongPassword();
405	    const conn = await connectNode(account.node);
406	    try {
407	      await applyIsolation(conn, { username: account.username, primaryDomain: account.primaryDomain, diskQuotaMB: account.diskQuotaMB, sftpPassword }, php);
408	    } finally {
409	      try { conn.end(); } catch { /* */ }
410	    }
411	    await db.hostingAccount.update({ where: { id: account.id }, data: { status: "ACTIVE", provisionedAt: new Date(), sftpPasswordEnc: encryptSecret(sftpPassword), error: null } });
412	  } catch (e) {
413	    await db.hostingAccount.update({ where: { id: account.id }, data: { status: "FAILED", error: (e instanceof Error ? e.message : String(e)).slice(0, 300) } });
414	  }
415	}
