424	/** True once `domain` resolves (A) to the node's shared IP — DNS is pointed at us. */
425	async function domainPointsAt(domain: string, ip: string): Promise<boolean> {
426	  try {
427	    const a = await dns.resolve4(domain);
428	    return a.includes(ip);
429	  } catch {
430	    return false;
431	  }
