434	/**
435	 * For each ACTIVE account without HTTPS, once its domain resolves to the node's
436	 * shared IP, issue a per-domain cert (webroot) and upgrade the vhost to a 443 SNI
437	 * block. Safe: touches only nginx + certbot, never sshd.
438	 */
439	export async function hostingSslSweep(): Promise<void> {
440	  if (SANDBOX || !ENABLED) return;
441	  const accts = await db.hostingAccount.findMany({
442	    where: { status: "ACTIVE", sslActive: false },
443	    include: { node: true },
444	    take: 20,
445	  });
446	  for (const a of accts) {
447	    try {
448	      if (!isValidHostingDomain(a.primaryDomain) || !isValidUnixUsername(a.username)) continue;
449	      if (!(await domainPointsAt(a.primaryDomain, a.node.publicIp))) continue; // DNS not pointed yet
450	      const d = a.primaryDomain;
451	      const conn = await connectNode(a.node);
452	      try {
453	        const issue = await exec(conn, `certbot certonly --webroot -w /var/www/html -d ${d} -d www.${d} --allow-subset-of-names --non-interactive --agree-tos --register-unsafely-without-email --keep-until-expiring 2>&1`, 3 * 60_000);
454	        const liveDir = `/etc/letsencrypt/live/${d}`;
455	        const have = await exec(conn, `test -s ${liveDir}/fullchain.pem && echo yes || echo no`);
456	        if (have.out.trim() !== "yes") { console.log(`[hosting] cert for ${d} not issued yet: ${issue.out.slice(0, 160)}`); continue; }
457	        const { webroot } = accountPaths(a.username);
458	        await installVhost(conn, a.username, renderHostingVhost(a.username, d, webroot, `/run/php/${a.username}.sock`, { certDir: liveDir, real: true }));
459	      } finally {
460	        try { conn.end(); } catch { /* */ }
461	      }
462	      await db.hostingAccount.update({ where: { id: a.id }, data: { sslActive: true } });
463	      console.log(`[hosting] HTTPS active for ${a.primaryDomain}`);
464	    } catch (e) {
465	      console.error(`[hosting] ssl sweep ${a.id} failed`, e);
466	    }
467	  }
468	
469	  // Addon domains get their own per-domain cert the same way, once they resolve
470	  // to the node's shared IP. (Subdomains are folded into the account cert below.)
471	  const addons = await db.hostingAddonDomain.findMany({
472	    where: { status: "ACTIVE", sslActive: false },
473	    include: { account: { include: { node: true } } },
474	    take: 20,
475	  });
476	  for (const ad of addons) {
477	    try {
478	      const u = ad.account.username;
479	      const d = ad.domain;
480	      if (!isValidHostingDomain(d) || !isValidUnixUsername(u)) continue;
481	      if (!(await domainPointsAt(d, ad.account.node.publicIp))) continue; // DNS not pointed yet
482	      const conn = await connectNode(ad.account.node);
483	      try {
484	        const issue = await exec(conn, `certbot certonly --webroot -w /var/www/html -d ${d} -d www.${d} --allow-subset-of-names --non-interactive --agree-tos --register-unsafely-without-email --keep-until-expiring 2>&1`, 3 * 60_000);
485	        const liveDir = `/etc/letsencrypt/live/${d}`;
486	        const have = await exec(conn, `test -s ${liveDir}/fullchain.pem && echo yes || echo no`);
487	        if (have.out.trim() !== "yes") { console.log(`[hosting] addon cert for ${d} not issued yet: ${issue.out.slice(0, 160)}`); continue; }
488	        const { docroot } = addonDomainPaths(u, d);
489	        await installNamedVhost(conn, `${u}-${d}`, renderSiteVhost(`${d} www.${d}`, docroot, `/run/php/${u}.sock`, liveDir));
490	      } finally {
491	        try { conn.end(); } catch { /* */ }
492	      }
493	      await db.hostingAddonDomain.update({ where: { id: ad.id }, data: { sslActive: true } });
494	      console.log(`[hosting] HTTPS active for addon ${d}`);
495	    } catch (e) {
496	      console.error(`[hosting] addon ssl sweep ${ad.id} failed`, e);
497	    }
498	  }
499	
500	  // Subdomains: fold each into its ACCOUNT'S existing Let's Encrypt cert as an
501	  // extra SAN once it resolves to the node, then serve 443 for it off that same
502	  // live dir. We reuse the account cert (HTTP-01 webroot, --expand) rather than a
503	  // wildcard: a wildcard needs DNS-01 + a DNS-provider API we don't hold (customers
504	  // self-manage their DNS), whereas SAN expansion works off the pointed A record —
505	  // the same flow every other cert here uses. The subdomain's HTTP vhost already
506	  // proxies /.well-known/acme-challenge to /var/www/html, so the challenge serves.
507	  const pendingSubs = await db.hostingSubdomain.findMany({
508	    where: { status: "ACTIVE", sslActive: false },
509	    include: { account: { include: { node: true } } },
510	    take: 30,
511	  });
512	  // One reissue per account per sweep even if several of its subdomains are pending
513	  // — the reissue covers them all at once, and each is verified independently below.
514	  const seenAccounts = new Set<string>();
515	  for (const sub of pendingSubs) {
516	    if (seenAccounts.has(sub.accountId)) continue;
517	    seenAccounts.add(sub.accountId);
518	    try {
519	      const a = sub.account;
520	      const u = a.username;
521	      const primary = a.primaryDomain;
522	      if (!isValidHostingDomain(primary) || !isValidUnixUsername(u)) continue;
523	      const liveDir = `/etc/letsencrypt/live/${primary}`;
524	      // All ACTIVE subdomains of this account, and which of them already resolve to
525	      // us. Only names that resolve are folded in, so certbot never churns on a name
526	      // it can't validate and the SAN set stays stable between ticks (idempotent).
527	      const active = await db.hostingSubdomain.findMany({ where: { accountId: a.id, status: "ACTIVE" } });
528	      const resolving: typeof active = [];
529	      for (const s of active) {
530	        if (!isValidSubdomainLabel(s.label)) continue;
531	        const fqdn = `${s.label}.${primary}`;
532	        if (!isValidHostingDomain(fqdn)) continue;
533	        if (await domainPointsAt(fqdn, a.node.publicIp)) resolving.push(s);
534	      }
535	      // Nothing to do until at least one not-yet-secured subdomain resolves to us.
536	      if (!resolving.some((s) => !s.sslActive)) continue;
537	      const conn = await connectNode(a.node);
538	      try {
539	        // The account cert must already exist (the primary sweep mints it once the
540	        // primary resolves). If it doesn't yet, leave it to that sweep and retry.
541	        if ((await exec(conn, `test -s ${liveDir}/fullchain.pem && echo yes || echo no`)).out.trim() !== "yes") continue;
542	        // SAN set = primary + www + every already-secured sub (never drop a live one)
543	        // + every currently-resolving sub. --cert-name pins the lineage to <primary>
544	        // so the live dir path is stable; --expand folds in the new SANs; --allow-
545	        // subset-of-names keeps a name that isn't pointed from aborting the cert;
546	        // --keep-until-expiring makes a no-op reissue idempotent when nothing changed.
547	        const keep = active.filter(
548	          (s) => (s.sslActive || resolving.includes(s)) && isValidSubdomainLabel(s.label) && isValidHostingDomain(`${s.label}.${primary}`),
549	        );
550	        const dflags = [primary, `www.${primary}`, ...keep.map((s) => `${s.label}.${primary}`)].map((n) => `-d ${n}`).join(" ");
551	        await exec(
552	          conn,
553	          `certbot certonly --webroot -w /var/www/html --cert-name ${primary} ${dflags} --expand --allow-subset-of-names --non-interactive --agree-tos --register-unsafely-without-email --keep-until-expiring 2>&1`,
554	          3 * 60_000,
555	        );
556	        // The reissue rewrote the cert in place. For each newly-securable sub, confirm
557	        // the cert now actually carries it as a SAN (a name whose challenge failed was
558	        // dropped by --allow-subset-of-names), then serve 443 for it off the account
559	        // live dir — installNamedVhost's nginx reload also loads the expanded cert.
560	        for (const s of resolving) {
561	          if (s.sslActive) continue; // already serving HTTPS — leave it untouched
562	          const fqdn = `${s.label}.${primary}`;
563	          const covered = (await exec(conn, `openssl x509 -in ${liveDir}/fullchain.pem -noout -text 2>/dev/null | grep -qiF 'DNS:${fqdn}' && echo yes || echo no`)).out.trim() === "yes";
564	          if (!covered) { console.log(`[hosting] subdomain ${fqdn} not yet in cert — retrying next tick`); continue; }
565	          const { docroot } = subdomainPaths(u, s.label);
566	          await installNamedVhost(conn, `${u}-${s.label}`, renderSiteVhost(fqdn, docroot, `/run/php/${u}.sock`, liveDir));
567	          await db.hostingSubdomain.update({ where: { id: s.id }, data: { sslActive: true } });
568	          console.log(`[hosting] HTTPS active for subdomain ${fqdn}`);
569	        }
570	      } finally {
571	        try { conn.end(); } catch { /* */ }
572	      }
573	    } catch (e) {
574	      console.error(`[hosting] subdomain ssl sweep ${sub.accountId} failed`, e);
575	    }
576	  }
577	}
