611	// ---- Node hardening sweep (admin "Run setup / harden") ---------------------
612	
613	/**
614	 * Run `scripts/onboard-hosting-node.sh` on ONE admin-QUEUED node over the
615	 * platform's EXISTING SSH path (the node's stored encrypted root password, the
616	 * same credential the account provisioner already uses). This lets the owner
617	 * harden a node — ModSecurity WAF + ClamAV + the hardening steps — WITHOUT ever
618	 * knowing the node's root password. The onboard script is idempotent and
619	 * `nginx -t`-guarded, so a re-run is safe and can't reload a broken config.
620	 *
621	 * NOT gated on ENABLE_SHARED_HOSTING: hardening is preparatory work that should
622	 * run before selling is switched on. Only the SANDBOX branch differs — there is
623	 * no real box to SSH into, so it just simulates the result. The sweep NEVER
624	 * hardens on its own initiative: it only acts on a node an admin explicitly set
625	 * to QUEUED (via adminHardenHostingNode).
626	 */
627	export async function hostingNodeHardenSweep(): Promise<void> {
628	  if (SANDBOX) {
629	    // No real SSH in sandbox — mark every queued node done so staging can drive
630	    // the whole button → badge → log flow without a box.
631	    const queued = await db.hostingNode.findMany({ where: { hardenStatus: "QUEUED" }, select: { id: true } });
632	    for (const n of queued) {
633	      await db.hostingNode
634	        .update({ where: { id: n.id }, data: { hardenStatus: "DONE", hardenedAt: new Date(), hardenLog: "[sandbox] onboard script simulated" } })
635	        .catch(() => undefined);
636	    }
637	    return;
638	  }
639	
640	  // One node per tick, oldest QUEUED first — the run is minutes long, so we
641	  // don't want to hold several SSH sessions open at once.
642	  const node = await db.hostingNode.findFirst({ where: { hardenStatus: "QUEUED" }, orderBy: { createdAt: "asc" } });
643	  if (!node) return;
644	  // Claim it immediately so the next tick can't pick the same node up again.
645	  await db.hostingNode.update({ where: { id: node.id }, data: { hardenStatus: "RUNNING" } });
646	
647	  try {
648	    // The worker's WorkingDirectory is the app root, so the script sits alongside.
649	    const script = readFileSync(join(process.cwd(), "scripts/onboard-hosting-node.sh"), "utf8");
650	    // Base64 the whole script and reconstitute it on the node — no quoting/heredoc
651	    // hazard reaches the shell, and the payload is a single opaque token.
652	    const b64 = Buffer.from(script, "utf8").toString("base64");
653	    const conn = await connectNode(node);
654	    try {
655	      // Decode → run → capture rc → always remove the temp script → exit with rc,
656	      // so a non-zero onboard exit is faithfully reported as FAILED. 2>&1 folds
657	      // stderr into the captured combined `out`.
658	      const cmd =
659	        `set -o pipefail; printf %s '${b64}' | base64 -d > /root/.nxeon-onboard.sh && ` +
660	        `bash /root/.nxeon-onboard.sh 2>&1; rc=$?; rm -f /root/.nxeon-onboard.sh; exit $rc`;
661	      const { code, out } = await exec(conn, cmd, HARDEN_TIMEOUT_MS);
662	      await db.hostingNode.update({
663	        where: { id: node.id },
664	        data: {
665	          hardenStatus: code === 0 ? "DONE" : "FAILED",
666	          hardenedAt: new Date(),
667	          hardenLog: out.slice(-HARDEN_LOG_MAX),
668	        },
669	      });
670	    } finally {
671	      try { conn.end(); } catch { /* */ }
672	    }
673	  } catch (e) {
674	    // Any SSH/read/timeout error must leave a terminal state — never a node stuck
675	    // in RUNNING (which the action-level guard would then refuse to re-queue).
676	    await db.hostingNode
677	      .update({
678	        where: { id: node.id },
679	        data: { hardenStatus: "FAILED", hardenedAt: new Date(), hardenLog: (e instanceof Error ? e.message : String(e)).slice(-HARDEN_LOG_MAX) },
680	      })
681	      .catch(() => undefined);
682	  }
683	}
