1121	/** (Re)write the account user's crontab from its ACTIVE cron rows. Runs `crontab
1122	 *  -u <user>` so every command runs AS the jailed user (confined). The whole
1123	 *  crontab is rebuilt each time (idempotent); a quoted heredoc prevents any shell
1124	 *  expansion, and each line is re-validated so nothing unsafe is ever written. */
1125	async function writeUserCrontab(conn: Client, username: string, accountId: string): Promise<void> {
1126	  if (!isValidUnixUsername(username)) throw new Error("unsafe account username");
1127	  const crons = await db.hostingCron.findMany({ where: { accountId, status: "ACTIVE" }, orderBy: { createdAt: "asc" } });
1128	  const lines = crons
1129	    .filter((c) => isValidCronSchedule(c.schedule) && isValidCronCommand(c.command))
1130	    .map((c) => `${c.schedule} ${c.command}`);
1131	  if (lines.length === 0) {
1132	    await run(conn, "clear crontab", `crontab -u ${username} -r 2>/dev/null || true`);
1133	    return;
1134	  }
1135	  const body = lines.join("\n") + "\n";
1136	  await run(conn, "write crontab", `crontab -u ${username} - <<'NXCRONEOF'\n${body}NXCRONEOF`);
1137	}
