1244	async function processHostingTask(taskId: string): Promise<void> {
1245	  const task = await db.hostingTask.findUnique({ where: { id: taskId }, include: { account: { include: { node: true } } } });
1246	  if (!task || task.status !== "PENDING") return;
1247	  await db.hostingTask.update({ where: { id: task.id }, data: { status: "RUNNING" } });
1248	  const a = task.account;
1249	  // Lifecycle tasks deliberately run on a NON-active account: the admin action
1250	  // flips status to SUSPENDED / DELETING *before* queuing, so gating them on ACTIVE
1251	  // (like the content tasks) would make suspend/terminate silent no-ops — the kill
1252	  // switch must still fire. Content tasks (PHP/WP/backup/restore) stay ACTIVE-only.
1253	  const isLifecycle = task.kind === "SUSPEND" || task.kind === "UNSUSPEND" || task.kind === "TERMINATE";
1254	  if (!isLifecycle && a.status !== "ACTIVE") { await failTask(task.id, "the account is not active"); return; }
1255	  try {
1256	    const conn = await connectNode(a.node);
1257	    try {
1258	      let result: string | null = null;
1259	      if (task.kind === "PHP_SWITCH") await taskPhpSwitch(conn, a, task.payload);
1260	      else if (task.kind === "WORDPRESS_INSTALL") result = await taskWordpressInstall(conn, a, task.payload);
1261	      else if (task.kind === "APP_INSTALL") result = await taskAppInstall(conn, a, task.payload);
1262	      else if (task.kind === "BACKUP") await taskBackup(conn, a, task.id);
1263	      else if (task.kind === "RESTORE") await taskRestore(conn, a, task.payload);
1264	      else if (task.kind === "SUSPEND") await taskSuspend(conn, a);
1265	      else if (task.kind === "UNSUSPEND") await taskUnsuspend(conn, a);
1266	      else if (task.kind === "TERMINATE") await taskTerminate(conn, a);
1267	      else if (task.kind === "CREATE_SUBDOMAIN") await taskCreateSubdomain(conn, a, task.payload);
1268	      else if (task.kind === "DELETE_SUBDOMAIN") await taskDeleteSubdomain(conn, a, task.payload);
1269	      else if (task.kind === "CREATE_ADDON_DOMAIN") await taskCreateAddonDomain(conn, a, task.payload);
1270	      else if (task.kind === "DELETE_ADDON_DOMAIN") await taskDeleteAddonDomain(conn, a, task.payload);
1271	      else if (task.kind === "CREATE_CRON") await taskCreateCron(conn, a, task.payload);
1272	      else if (task.kind === "DELETE_CRON") await taskDeleteCron(conn, a, task.payload);
1273	      else if (task.kind === "INSTALL_DBTOOL") result = await taskInstallDbTool(conn, a, task.payload);
1274	      else if (task.kind === "ENSURE_DBMGR") await taskEnsureDbMgr(conn, a);
1275	      else if (task.kind === "APPLY_PLAN_LIMITS") await taskApplyPlanLimits(conn, a);
1276	      await db.hostingTask.update({ where: { id: task.id }, data: { status: "DONE", result, error: null } });
1277	    } finally { try { conn.end(); } catch { /* */ } }
