762	  const name = normalizeHostingDomain(domain);
763	  if (!name || !isValidHostingDomain(name)) return { error: "Enter a valid domain (e.g. example.com)." };
764	  if (name === a.primaryDomain) return { error: "That’s already your primary domain." };
765	  // Cross-tenant uniqueness across ALL three hostname tables — a shared vhost keys
766	  // on server_name, so an addon must not shadow anyone's primary, subdomain, or
767	  // addon (audit HIGH-1: this used to omit HostingSubdomain.fqdn).
768	  if (await isHostnameClaimed(name)) {
