770	  }
771	  const { docroot } = addonDomainPaths(a.username, name);
772	  try {
773	    await db.$transaction(async (tx) => {
774	      const subs = await tx.hostingSubdomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
775	      const addons = await tx.hostingAddonDomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
776	      if (subs + addons >= a.maxSites) throw new Error("CAP");
777	      const addon = await tx.hostingAddonDomain.create({ data: { accountId: a.id, domain: name, docroot, status: "PENDING" } });
778	      await tx.hostingTask.create({ data: { accountId: a.id, kind: "CREATE_ADDON_DOMAIN", payload: JSON.stringify({ addonId: addon.id }) } });
779	    }, { isolationLevel: "Serializable" });
780	  } catch (e) {
781	    if (e instanceof Error && e.message === "CAP") return { error: siteCapMessage(a.maxSites) };
782	    return { error: "That domain is already added, or the request raced — try again." };
783	  }
784	  revalidatePath(`/dashboard/hosting/${accountId}`);
